COPY tarification.ref_base_calcul (code, libelle, description) FROM stdin;
VALEUR_ASSUREE_OBJET	Valeur assurée de l'objet	Lit criteres_objet/caracteristiques_objet.valeur_assuree
CAPITAL_GARANTIE_CHOISI	Capital de garantie choisi (palier)	Palier fixe choisi par le souscripteur — forfait, pas un pourcentage
PRIME_ELEMENT_MEME_POLICE	Une autre ligne de prime de la même police	Dépend d'un prime_elements.id précédent
SOMME_PRIMES_FLOTTE	Somme des primes d'une flotte	Dépend de la somme des primes de plusieurs polices regroupées
GRILLE_ZONE_FORCE_FISCALE	Grille par zone/force fiscale/tonnage...	Lecture directe dans baremes_tranches, cas standard
NOMBRE_PLACES_VEHICULE	Nombre de places du véhicule	Le montant stocké est un tarif PAR PLACE — la prime réelle est ce montant multiplié par le nombre de places du véhicule assuré.
\.
COPY tarification.regles_calcul (id, code, libelle, mode_calcul, base_calcul_code, formule, description) FROM stdin;
1	AUTO_BAREME_FF_ZONE	Barème RC automobile par force fiscale, zone et remorque	BAREME_TRANCHE	GRILLE_ZONE_FORCE_FISCALE	lookup(force_fiscale, zone, avec_remorque) -> montant_fixe	\N
2	IPT_FORFAIT_PALIER	Forfait par formule (1 à 4) - IPT/IAC	MONTANT_FORFAITAIRE	CAPITAL_GARANTIE_CHOISI	lookup(formule_choisie) -> montant_fixe	\N
5	TAUX_POURCENTAGE_SIMPLE	Taux % de la valeur assurée, sans tranche	TAUX_POURCENTAGE	VALEUR_ASSUREE_OBJET	valeur_assuree x taux_pct	\N
6	VOL_TAUX_AGE_VEHICULE	Taux Vol selon âge du véhicule	TAUX_POURCENTAGE	VALEUR_ASSUREE_OBJET	valeur_assuree x taux_pct, tranche selon age_vehicule_annees	\N
11	NOMBRE_PLACES_FORFAIT_PAR_PLACE	Forfait par place, multiplie par le nombre de places du vehicule	MONTANT_FORFAITAIRE	NOMBRE_PLACES_VEHICULE	montant_fixe x nombre_places_vehicule	\N
12	DR_POURCENTAGE_RC	Défense et recours, % de la prime RC	TAUX_POURCENTAGE	PRIME_ELEMENT_MEME_POLICE	prime_RC_deja_calculee x taux_pct -- subordonne a garantie_liens mode ASSIETTE	\N
\.
